mapper.select:
SELECT EQP_G, EQP_ID, COMMON_ID, LISTAGG(CHAMBER,'|') WITHIN GROUP (ORDER BY CHAMBER) CHAMBER,MAX(PREV_E10_STATE_CODE)||' '||MAX(PREV_STATE) PREV_STATE FROM (SELECT A.EQP_G, A.EQP_ID, A.CHAMBER_ID, NVL(B.COMMON_ID, A.CHAMBER_ID) COMMON_ID, SUBSTR(A.CHAMBER_ID, INSTR(A.CHAMBER_ID, '.') + 1) CHAMBER ,A.PREV_STATE,A.PREV_E10_STATE_CODE FROM (SELECT T.EQP_G, SUBSTR(T.EQP_ID, 1, 5) EQP_ID, T.EQP_ID CHAMBER_ID, T.PREV_E10_STATE_CODE,T.PREV_STATE, T.FAB_ID FROM PWEB.EQP_ID_USE_STD T WHERE T.MIN_UNIT_FLAG = 'Y' AND MODULE=#{module} AND T.EQP_G=#{eqpg}
AND T.ACTIVE_FLAG = 'Y'
)A,(SELECT LINE, KEY1 AS MODULE, KEY2 AS EQP_G, KEY3 AS EQP_ID, KEY4 AS CHAMBER_ID, KEY5 AS COMMON_ID, F_COMMENT AS TWINS_CHAMBER,UPDATE_TIME, UPDATE_USER FROM PWEB.FUNCTION_SETTING T WHERE FUNCTION_NAME = 'Abnormal_System' AND FUNCTION_KEY = 'TwinsChamber' AND LINE = 'N11')B WHERE A.CHAMBER_ID=B.CHAMBER_ID(+)) GROUP BY EQP_G,EQP_ID,COMMON_ID ORDER BY COMMON_ID

SELECT EQP_G, EQP_ID, COMMON_ID, LISTAGG(CHAMBER,'|') WITHIN GROUP (ORDER BY CHAMBER) CHAMBER,MAX(PREV_E10_STATE_CODE)||' '||MAX(PREV_STATE) PREV_STATE FROM (SELECT A.EQP_G, A.EQP_ID, A.CHAMBER_ID, NVL(B.COMMON_ID, A.CHAMBER_ID) COMMON_ID, SUBSTR(A.CHAMBER_ID, INSTR(A.CHAMBER_ID, '.') + 1) CHAMBER ,A.PREV_STATE,A.PREV_E10_STATE_CODE FROM (SELECT T.EQP_G, SUBSTR(T.EQP_ID, 1, 6) EQP_ID, T.EQP_ID CHAMBER_ID, T.PREV_E10_STATE_CODE,T.PREV_STATE, T.FAB_ID FROM PWEB.EQP_ID_USE_STD T WHERE T.MIN_UNIT_FLAG = 'Y' AND MODULE=#{module} AND T.EQP_G=#{eqpg}
AND T.ACTIVE_FLAG = 'Y'
)A,(SELECT LINE, KEY1 AS MODULE, KEY2 AS EQP_G, KEY3 AS EQP_ID, KEY4 AS CHAMBER_ID, KEY5 AS COMMON_ID, F_COMMENT AS TWINS_CHAMBER,UPDATE_TIME, UPDATE_USER FROM PWEB.FUNCTION_SETTING T WHERE FUNCTION_NAME = 'Abnormal_System' AND FUNCTION_KEY = 'TwinsChamber' AND LINE = 'N11')B WHERE A.CHAMBER_ID=B.CHAMBER_ID(+)) GROUP BY EQP_G,EQP_ID,COMMON_ID ORDER BY COMMON_ID

