(
SELECT 'ALL' TEXT,'ALL' VAL FROM DUAL
UNION ALL
SELECT DISTINCT PRODG1 TEXT,PRODG1 VAL FROM A1_MFG.ETCH_CLOSE_PATH_DETAIL_COMM WHERE EQP_G=#{eqpg}
AND FAB=#{fab}
) ORDER BY TEXT

